import React, { useState, useRef, useEffect } from 'react';
import axios from 'axios';
import { API_URL, testConnection } from '../utils/api';

const ImageProcessor = ({ colorblindType, mode }) => {
  const [originalImage, setOriginalImage] = useState(null);
  const [processedImage, setProcessedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [serverConnected, setServerConnected] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    testConnection().then(r => setServerConnected(r.success));
  }, []);

  const handleFile = (file) => {
    if (!file || !file.type.startsWith('image/')) return;
    const reader = new FileReader();
    reader.onload = e => {
      setOriginalImage(e.target.result);
      setProcessedImage(null);
      setError(null);
    };
    reader.readAsDataURL(file);
  };

  const handleFileSelect = (e) => {
    handleFile(e.target.files[0]);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.currentTarget.classList.remove('dragover');
    handleFile(e.dataTransfer.files[0]);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.currentTarget.classList.add('dragover');
  };

  const handleDragLeave = (e) => {
    e.currentTarget.classList.remove('dragover');
  };

  const processImage = async () => {
    if (!originalImage) return;
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(originalImage);
      const blob = await response.blob();

      const formData = new FormData();
      formData.append('image', blob, 'image.jpg');
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const res = await axios.post(`${API_URL}/process-image`, formData);
      setProcessedImage(`data:image/jpeg;base64,${res.data.processed_image}`);
    } catch {
      setError('Failed to process image');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="component-container">
      <h2>Image Processor</h2>

      <div
        className="upload-area"
        onClick={() => fileInputRef.current.click()}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleFileSelect}
          hidden
        />
        <p>Click or drag and drop an image here</p>
        <p className="subtext">Supported formats: JPG, PNG, GIF</p>
      </div>

      {error && <div className="error">{error}</div>}

      <div className="preview-row">
        {originalImage && (
          <div className="preview">
            <h3>Original</h3>
            <img src={originalImage} alt="Original" />
          </div>
        )}
        {processedImage && (
          <div className="preview">
            <h3>Processed</h3>
            <img src={processedImage} alt="Processed" />
          </div>
        )}
      </div>

      <button
        className="button"
        onClick={processImage}
        disabled={!originalImage || loading}
      >
        {loading ? 'Processing...' : 'Process Image'}
      </button>
    </div>
  );
};

export default ImageProcessor;
